gun_ay = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

def gun_ekle(ay, gun, n):
    while n > 0:
        kalan = gun_ay[ay - 1] - gun
        if n <= kalan:
            gun = gun + n
            n = 0
        else:
            n = n - kalan - 1
            gun = 1
            ay = ay + 1
    return (ay, gun)

